#!/usr/bin/env python3
"""Generates .github/workflows/build.yml (a chain of resumable build stages).

GitHub Actions has no loops, so the 16 near-identical stage jobs are written
out by this script. Edit here, then run:  python tools/gen_build_workflow.py
"""

from pathlib import Path

STAGES = 16
OUT = Path(__file__).resolve().parent.parent / '.github' / 'workflows' / 'build.yml'

HEAD = '''\
# GENERATED by tools/gen_build_workflow.py - edit that script, not this file.
#
# Builds Bastion for Windows x64 on free GitHub-hosted runners.
# A full Chromium build takes far longer than one job's 6-hour limit, so it
# runs as a chain of stages that each build ~3.5h and hand the half-built
# tree to the next one (expect roughly a day end to end).
#
# Runs when:
#   * a tag is pushed (e.g. 157.0.8103.78-1) -> build + publish that Release
#   * started by hand (Actions tab -> build -> Run workflow) -> build, then
#     publish a Release tagged with the version from config/bastion.toml
#     (untick "Publish a release" for a test build; the installer is then
#     only kept as a run artifact for 4 days)
name: build
on:
  workflow_dispatch:
    inputs:
      publish_release:
        description: Publish a GitHub Release when the build finishes
        type: boolean
        default: true
  push:
    tags:
      - '*'

permissions:
  contents: read

concurrency:
  group: build-${{ github.ref }}
  cancel-in-progress: false

jobs:
  check-patches:
    name: Check patches apply (Linux, fast)
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v7
        with:
          submodules: recursive
      - uses: ./.github/actions/free-disk-space
      - uses: actions/setup-python@v6
        with:
          python-version: '3.12'
      - name: Apply every patch to the official Chromium source
        run: python tools/check_patches.py --workdir "$RUNNER_TEMP/work" --cache "$RUNNER_TEMP/cache"
'''

STAGE = '''
  build-{n}:
    name: Build stage {n}
    needs: {needs}
    runs-on: windows-2022
    steps:
      - uses: actions/checkout@v7
        with:
          submodules: recursive
      - uses: ./.github/actions/prepare
      - name: Build
        id: stage
        uses: ./.github/actions/stage
        env:
          BASTION_GOOGLE_API_KEY: ${{{{ secrets.BASTION_GOOGLE_API_KEY }}}}
        with:
          finished: {finished}
          from_artifact: {from_artifact}
    outputs:
      finished: ${{{{ steps.stage.outputs.finished }}}}
'''

TAIL = '''
  release:
    name: Publish release
    needs: build-{last}
    runs-on: ubuntu-latest
    permissions:
      contents: write
    steps:
      - name: Make sure the build finished
        run: |
          if [ "${{{{ needs.build-{last}.outputs.finished }}}}" != "true" ]; then
            echo "Build did not finish after {last} stages."
            exit 1
          fi
      - name: Download packages
        uses: actions/download-artifact@v8
        with:
          name: bastion-x64
          path: dist
      - name: Checksums
        run: cd dist && sha256sum bastion_* | tee SHA256SUMS.txt
      - name: Work out the release tag
        id: tag
        run: |
          if [ "${{{{ github.ref_type }}}}" = "tag" ]; then
            tag="${{{{ github.ref_name }}}}"
          else
            # The version the packages were built as, e.g. bastion_157.0.8103.78-1_installer_x64.exe
            f=$(ls dist | grep '_installer_' | head -n1)
            tag=${{f#bastion_}}
            tag=${{tag%%_installer_*}}
          fi
          [ -n "$tag" ] || {{ echo "Could not determine the release tag"; exit 1; }}
          echo "tag=$tag" >> "$GITHUB_OUTPUT"
      - name: Publish GitHub Release
        if: github.ref_type == 'tag' || inputs.publish_release
        uses: softprops/action-gh-release@v3
        with:
          tag_name: ${{{{ steps.tag.outputs.tag }}}}
          target_commitish: ${{{{ github.sha }}}}
          name: Bastion ${{{{ steps.tag.outputs.tag }}}}
          fail_on_unmatched_files: true
          overwrite_files: true
          body: |
            Bastion for Windows x64, version `${{{{ steps.tag.outputs.tag }}}}`.

            * `bastion_*_installer_x64.exe` installs for your Windows user (no admin needed).
            * `bastion_*_windows_x64.zip` is portable: unzip it and run `chrome.exe`.

            SHA-256 checksums are in `SHA256SUMS.txt`.
          files: |
            dist/bastion_*
            dist/SHA256SUMS.txt
'''


def main():
    text = HEAD
    for n in range(1, STAGES + 1):
        if n == 1:
            text += STAGE.format(n=n, needs='check-patches', finished='false', from_artifact='false')
        else:
            prev = f'build-{n - 1}'
            text += STAGE.format(n=n, needs=prev,
                                 finished=f'${{{{ needs.{prev}.outputs.finished }}}}',
                                 from_artifact='true')
    text += TAIL.format(last=STAGES)
    OUT.write_text(text, encoding='utf-8')
    print(f'Wrote {OUT}')


if __name__ == '__main__':
    main()
